bash -lc python - <<'PY'
from pptx import Presentation
orig='/mnt/data/数据资产化背景下医疗多源暗数据的激活路径与质量治理研究.pptx'
new='/mnt/data/数据资产化背景下医疗多源暗数据的激活路径与质量治理研究_美化版.pptx'
for label,path in [('orig',orig),('new',new)]:
    prs=Presentation(path)
    pics=sum(1 for s in prs.slides for sh in s.shapes if sh.shape_type==13)
    texts=[]
    for s in prs.slides:
        for sh in s.shapes:
            if getattr(sh,'has_text_frame',False) and sh.text:
                texts.append(sh.text)
    print(label, 'slides', len(prs.slides), 'pictures', pics, 'texts', len(texts), 'chars', sum(len(t) for t in texts))
    # print(texts[:3])
orig_texts=[]; new_texts=[]
for s in Presentation(orig).slides:
    for sh in s.shapes:
        if getattr(sh,'has_text_frame',False) and sh.text:
            orig_texts.append(sh.text)
for s in Presentation(new).slides:
    for sh in s.shapes:
        if getattr(sh,'has_text_frame',False) and sh.text:
            new_texts.append(sh.text)
print('text lists equal:', orig_texts==new_texts[:len(orig_texts)])
# compare as counter
from collections import Counter
print('counter equal:', Counter(orig_texts)==Counter(new_texts))
missing = Counter(orig_texts)-Counter(new_texts)
extra = Counter(new_texts)-Counter(orig_texts)
print('missing', missing)
print('extra', extra)
