bash -lc python - <<'PY'
from pptx import Presentation
p='/mnt/data/数据资产化背景下医疗多源暗数据的激活路径与质量治理研究_美化版.pptx'
prs=Presentation(p)
W,H=prs.slide_width,prs.slide_height
bad=[]
for si,s in enumerate(prs.slides,1):
    for sh in s.shapes:
        if sh.left < 0 or sh.top < 0 or sh.left+sh.width > W+10000 or sh.top+sh.height > H+10000:
            bad.append((si,sh.name,sh.left,sh.top,sh.width,sh.height,sh.left+sh.width-W,sh.top+sh.height-H))
print('out of bounds', len(bad))
for b in bad[:20]: print(b)
# picture count, text preserved
orig='/mnt/data/数据资产化背景下医疗多源暗数据的激活路径与质量治理研究.pptx'
from collections import Counter
orig_texts=[]; new_texts=[]
for s in Presentation(orig).slides:
    for sh in s.shapes:
        if getattr(sh,'has_text_frame',False) and sh.text:
            orig_texts.append(sh.text)
for s in prs.slides:
    for sh in s.shapes:
        if getattr(sh,'has_text_frame',False) and sh.text:
            new_texts.append(sh.text)
print('text counter equal', Counter(orig_texts)==Counter(new_texts))
print('pics', sum(1 for s in Presentation(orig).slides for sh in s.shapes if sh.shape_type==13), sum(1 for s in prs.slides for sh in s.shapes if sh.shape_type==13))
